draw:
var beta = p.beta;
var gam = 1 / Math.sqrt(1 - beta * beta);
var pad = 30;
var font = "12px ui-sans-serif, system-ui, sans-serif";

// mirror separation in pixels, shrunk so two slanted legs still fit the canvas
var d = Math.min(0.34 * H, (W - 2 * pad) / (2 * beta * gam + 0.6));
var yTop = 0.26 * H;
var yBot = yTop + d;
var adv = beta * gam * d;          // horizontal advance per one-way leg
var x0 = pad + 10;

// mirrors at the three positions the clock occupies at the two turning points
ctx.lineWidth = 2;
var k;
for (k = 0; k < 3; k++) {
  var xc = x0 + k * adv;
  ctx.strokeStyle = k === 0 ? C.figure : C.faint;
  ctx.beginPath();
  ctx.moveTo(xc - 16, yBot); ctx.lineTo(xc + 16, yBot);
  ctx.moveTo(xc - 16, yTop); ctx.lineTo(xc + 16, yTop);
  ctx.stroke();
}

// the light path: down-up zigzag
ctx.lineWidth = 1.5;
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath();
ctx.moveTo(x0, yBot);
ctx.lineTo(x0 + adv, yTop);
ctx.lineTo(x0 + 2 * adv, yBot);
ctx.stroke();
ctx.setLineDash([]);

// the vertical leg the clock's own frame sees
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(x0, yBot); ctx.lineTo(x0, yTop); ctx.stroke();

// animate the photon over one full round trip, then pause
var period = 3.2;
var ph = (t % period) / period;
var leg = ph * 2;
var px, py;
if (leg < 1) { px = x0 + adv * leg; py = yBot + (yTop - yBot) * leg; }
else { px = x0 + adv * leg; py = yTop + (yBot - yTop) * (leg - 1); }
if (leg > 2) { px = x0 + 2 * adv; py = yBot; }
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px, py, 4.5, 0, Math.PI * 2); ctx.fill();

// travelled part of the slanted path
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x0, yBot);
if (leg < 1) ctx.lineTo(px, py);
else { ctx.lineTo(x0 + adv, yTop); ctx.lineTo(px, py); }
ctx.stroke();

// labels
ctx.font = font;
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("d", x0 - 5, (yTop + yBot) / 2 + 4);
ctx.textAlign = "center";
ctx.fillText("v Δt", x0 + adv / 2, yBot + 18);
ctx.fillStyle = C.figure;
ctx.fillText("c Δt", x0 + adv / 2 - 14, (yTop + yBot) / 2 - 6);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("mirror", x0 + 20, yTop - 8);
ctx.fillText("mirror", x0 + 20, yBot + 18);

// base line marking the horizontal drift
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(x0, yBot + 8); ctx.lineTo(x0 + adv, yBot + 8); ctx.stroke();

var d0 = p.sep;
var tick0 = 2 * d0 / 3e8 * 1e9;
out.note = "gamma " + gam.toFixed(3) + "  |  round trip " + tick0.toFixed(1) +
  " ns on the clock itself, " + (gam * tick0).toFixed(1) + " ns in the lab";
